/**
 * Check a row limit option. Undefined and Infinity mean no limit.
 *
 * @param {unknown} limit
 */
export function validateLimit(limit) {
  if (limit === undefined || limit === Infinity) return
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
    throw new Error('parquet limit must be a non-negative integer')
  }
}

/**
 * Concatenate two arrays fast.

export async function parquetQuery(options) {
  const { limit } = options
  validateLimit(limit)
  // limit applies to the final rows, so the inner reads must not see it
  const rows = await queryRows({ ...options, limit: undefined })
  return rows.slice(0, limit)
}

